/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        item
    } = event.context;

    let feature = '';
    let detail = 'Documentation';
    let label = item.value.link.label;
    if (label == "CMDB application for API's and CLI") {
        feature = 'CLI API';
    } else if (label == "IntegrationHub ETL") {
        feature = 'IHETL';
    } else if (label == "Service Graph Connectors") {
        feature = 'SGC';
    } else if (label == "CMDB Data Manager") {
        feature = 'Data Manager';
    } else if (label == "Data attestation") {
        feature = 'Data Attestation';
    } else if (label == "Data Sync") {
        feature = 'Data Sync';
    } else if (label == "Princiapl Classes") {
        feature = 'Principal Classes';
    } else if (label == "CMDB Health dashboard") {
        feature = 'CMDB Health Dashboard';
    } else if (label == "Data Foundation dashboard") {
        feature = 'Data Foundations Dashboard';
    } else if (label == "CMDB 360 queries") {
        feature = 'CMDB 360 Queries';
    } else if (label == "CMDB Query Builder") {
        feature = 'Query Builder';
    } else if (label == "Intelligent search") {
        feature = 'Intelligent Search';
    }

    let parent = item.parent.value.label;

    let eventName = 'Click ' + parent.toLowerCase();
    let status = item.value.badge.positive;
    if (status) {
        detail = 'Open application';
    } else {
        detail = 'Documentation';
    }

    return {
        event: eventName,
        value: {
            'Source': 'Adoption Progress',
            'Feature': feature,
            'Detail': detail
        }
    };
}
